{
  "гриб": "Amanita citrina (лимонный мухомор)",
  "состав": [
    {
      "вещество": "α-Аманитин (цикло-8-пептид)",
      "содержание": "переменное, ориентировочно 0,05–0,5 % от сухого веса (ниже, чем у A. phalloides)",
      "влияние": "Надёжно ингибирует РНК-полимеразу II, нарушая синтез белка и вызывая некроз клеток печени, почек и кишечника с возможным летальным исходом."
    },
    {
      "вещество": "β-Аманитин",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Обладает слабой гепатотоксичностью и тоже подавляет РНК-полимеразу II, но в меньшей степени, чем α-аманитин."
    },
    {
      "вещество": "β-Изоокситоцин",
      "содержание": "неизвестно (мелкие следовые количества в группе аманитов)",
      "влияние": "Проявляет слабый антихолинэстеразный и нейротоксический эффект, способствуя общему отравляющему действию гриба."
    },
    {
      "вещество": "Витиоцин и конвиоцин (пуриновые нуклеотиды)",
      "содержание": "неизвестно (отмечаются в некоторых видах Amanita секции Validae)",
      "влияние": "Можно вызывать гемолиз эритроцитов и усугублять почечную недостаточность при тяжёлом отравлении."
    }
  ]
}

{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря)",
  "состав": [
    {
      "вещество": "Белки (аминокислоты: глутаминовая, аспарагиновая, аланин, глицин, лейцин и др.)",
      "содержание": "2,5–4 % от свежего веса (≈25–30 % от сухого веса)",
      "влияние": "Поступают в организм как пищевой белок; глутамат обеспечивает характерный умами-вкус и не оказывает токсического действия."
    },
    {
      "вещество": "Хитин (полисахарид клеточной стенки)",
      "содержание": "≈1–2 % от свежего веса",
      "влияние": "Не усваивается полностью; действует как пищевое волокно, мягко стимулируя перистальтику кишечника."
    },
    {
      "вещество": "Гликоген и трегалоза",
      "содержание": "≈2–4 % от сухого веса",
      "влияние": "Являются доступным источником быстрых углеводов; расщепляются ферментами ЖКТ до глюкозы."
    },
    {
      "вещество": "Эргостерол (стерол)",
      "содержание": "3–6 мг/100 г свежего веса",
      "влияние": "При фотолитическом распаде образует витамин D₂; в обычных пищевых количествах физиологической значимости для человека не имеет."
    },
    {
      "вещество": "Витамин D₂ (эргокальциферол)",
      "содержание": "неизвестно (следовые количества, зависят от освещённости)",
      "влияние": "Участвует в метаболизме кальция и фосфора; в пищевых дозах не вызывает гипервитаминоза."
    },
    {
      "вещество": "Витамины группы B (рибофлавин, ниацин, фолиевая кислота)",
      "содержание": "неизвестно (следовые, до нескольких мг/кг)",
      "влияние": "Выступают коферментами в энергетическом обмене; в съедобных порциях вклад в суточную норму незначителен."
    },
    {
      "вещество": "Калий",
      "содержание": "≈350–500 мг/100 г свежего веса",
      "влияние": "Поддерживает осмотическое и электролитное равновесие; избыток у лиц с почечной недостаточностью может вызывать гиперкалиемию."
    },
    {
      "вещество": "Фосфор",
      "содержание": "≈100–180 мг/100 г свежего веса",
      "влияние": "Входит в состав АТФ, нуклеотидов и фосфолипидов; в пищевых дозах обеспечивает энергетический обмен без токсического эффекта."
    },
    {
      "вещество": "Железо, цинк, медь, марганец (микроминералы)",
      "содержание": "Fe ≈ 2–4 мг/100 г; Zn ≈ 1–2 мг/100 г; Cu, Mn — следы (мкг/г)",
      "влияние": "Являются кофакторами ферментов (гемо-, цинк-, медьсодержащих); в пищевых концентрациях не достигают токсичных уровней."
    },
    {
      "вещество": "Сапонины (стериновые)",
      "содержание": "неизвестно (мг/кг, следовые)",
      "влияние": "В малых дозах не оказывают ощутимого действия; при избытке способны раздражать слизистую ЖКТ."
    },
    {
      "вещество": "Амато- и фаллотоксины (пептидные яды родства)",
      "содержание": "отсутствуют / < 0,1 мг/кг (ниже предела детекции)",
      "влияние": "При их отсутствии ядовитое действие не проявляется, что делает вид съедобным."
    },
    {
      "вещество": "Липиды (линолевая, пальмитиновая, олеиновая кислоты)",
      "содержание": "≈0,5–1 % от свежего веса",
      "влияние": "Составная часть мембран; в пищевых количествах не вносят существенного вклада в липидный профиль рациона."
    }
  ]
}
